package online.wydmeal.reservation;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.location.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Native location + restaurant picker. Search uses the existing authenticated proxy. */
public final class PlacePickerActivity extends Activity {
 private MapPanel mapPanel;private NativeUi ui;private ApiClient api;private EditText city,keyword;private LinearLayout results,root;private TextView summary;private final Handler handler=new Handler();private final ExecutorService worker=Executors.newSingleThreadExecutor();private final ArrayList<JSONObject> places=new ArrayList<>();private LocationManager locations;private LocationListener listener;private double lat=Double.NaN,lng=Double.NaN;private boolean busy,more;private int page=1;private String searchCity="",searchWord="",locationCity="";
 @Override public void onCreate(Bundle state){Appearance.apply(this);super.onCreate(state);ui=new NativeUi(this);api=new ApiClient(this);root=ui.column();root.setBackgroundColor(ui.bg);setContentView(root);getWindow().getDecorView().setSystemUiVisibility(ui.dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets b=insets.getInsets(WindowInsets.Type.systemBars()),ime=insets.getInsets(WindowInsets.Type.ime());v.setPadding(b.left,b.top,b.right,Math.max(b.bottom,ime.bottom));return insets;});}else root.setFitsSystemWindows(true);
  LinearLayout head=ui.row();head.setPadding(ui.dp(12),ui.dp(8),ui.dp(20),ui.dp(8));FrameLayout back=new FrameLayout(this);back.addView(ui.icon("back",ui.primary),new FrameLayout.LayoutParams(-1,-1));back.setContentDescription("返回预约表单");back.setOnClickListener(v->finish());head.addView(back,new LinearLayout.LayoutParams(ui.dp(48),ui.dp(48)));head.addView(ui.text("选择餐厅",21,ui.text,true));root.addView(head);
  ScrollView scroll=new ScrollView(this);LinearLayout content=ui.column();content.setPadding(ui.dp(20),ui.dp(8),ui.dp(20),ui.dp(24));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));city=ui.input(content,"城市 · 必填","",android.text.InputType.TYPE_CLASS_TEXT);keyword=ui.input(content,"餐厅名称或地址","",android.text.InputType.TYPE_CLASS_TEXT);ui.fullButton(content,"使用当前位置",false,()->locate());ui.fullButton(content,"搜索餐厅",true,()->search(true));summary=ui.text("可先定位，也可手动填写城市。",14,ui.muted,false);ui.gap(content,16);content.addView(summary);mapPanel=new MapPanel(this,ui,content,state,new MapPanel.Pick(){public void point(double lat,double lng){pickPoint(lat,lng);}public void place(JSONObject place){if(!place.optString("id").isEmpty())pickDetails(place);else selectPlace(place);}});results=ui.column();ui.gap(content,16);content.addView(results);
  if(state!=null){city.setText(state.getString("city",""));keyword.setText(state.getString("keyword",""));lat=state.getDouble("lat",Double.NaN);lng=state.getDouble("lng",Double.NaN);locationCity=state.getString("locationCity","");}
 }
 private void error(String text){if(!isFinishing())new AlertDialog.Builder(this).setTitle("地点搜索").setMessage(text).setPositiveButton("知道了",null).show();}
 private void search(boolean reset){if(busy)return;String c=city.getText().toString().trim(),q=keyword.getText().toString().trim();if(c.isEmpty()){city.setError("请填写城市或使用定位");return;}if(q.isEmpty()){keyword.setError("请填写餐厅名称或地址");return;}if(reset){if(!c.equals(locationCity)){lat=Double.NaN;lng=Double.NaN;}places.clear();page=1;searchCity=c;searchWord=q;}else if(!searchCity.equals(c)||!searchWord.equals(q)){search(true);return;}
  busy=true;summary.setText("正在查找餐厅…");JSONObject payload=ApiClient.object("action","search","city",c,"keyword",q,"page",page);try{if(Double.isFinite(lat)){payload.put("lat",lat);payload.put("lng",lng);}}catch(Exception ignored){}
  worker.execute(()->{try{JSONObject data=api.json("/api/map-service",payload);handler.post(()->{if(isDestroyed())return;busy=false;JSONArray list=data.optJSONArray("places");if(list!=null)for(int i=0;i<list.length();i++){JSONObject place=list.optJSONObject(i);boolean exists=false;for(JSONObject old:places)if(old.optString("name").equals(place.optString("name"))&&old.optString("address").equals(place.optString("address")))exists=true;if(!exists)places.add(place);}more=data.optBoolean("hasMore");page=data.optInt("nextPage",page+1);showPlaces();});}catch(Exception e){handler.post(()->{if(isDestroyed())return;busy=false;summary.setText("搜索失败，可重新尝试。");error(e.getMessage());});}});
 }
 private double distance(JSONObject p){if(!Double.isFinite(lat))return 0;float[] result=new float[1];Location.distanceBetween(lat,lng,p.optDouble("lat"),p.optDouble("lng"),result);return result[0];}
 private void showPlaces(){results.removeAllViews();if(Double.isFinite(lat))places.sort((a,b)->Double.compare(distance(a),distance(b)));summary.setText("已找到 "+places.size()+" 个地点"+(Double.isFinite(lat)?" · 附近50公里，按距离排序":" · 所选城市内搜索"));mapPanel.show(places);for(JSONObject p:places){LinearLayout card=ui.card(results);card.addView(ui.text(p.optString("name"),20,ui.text,true));ui.gap(card,8);card.addView(ui.body(p.optString("address")));if(Double.isFinite(lat)){ui.gap(card,8);double d=distance(p);card.addView(ui.text(d>=1000?String.format(Locale.CHINA,"距当前位置 %.1f 公里",d/1000):String.format(Locale.CHINA,"距当前位置 %.0f 米",d),14,ui.primary,true));}ui.fullButton(card,"选择此餐厅",true,()->{selectPlace(p);});}if(more)ui.fullButton(results,"加载更多餐厅",false,()->search(false));if(places.isEmpty())results.addView(ui.body("没有找到匹配的餐厅，请尝试分店名称或其他关键词。"));}
 private void locate(){if(busy)return;if(checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.ACCESS_FINE_LOCATION},100);return;}summary.setText("正在获取当前位置…");locations=(LocationManager)getSystemService(LOCATION_SERVICE);Location best=null;try{for(String provider:locations.getProviders(true)){Location candidate=locations.getLastKnownLocation(provider);if(candidate!=null&&(best==null||candidate.getTime()>best.getTime()))best=candidate;}if(best!=null&&System.currentTimeMillis()-best.getTime()<120000){position(best);return;}
  listener=new LocationListener(){public void onLocationChanged(Location location){if(listener==null)return;locations.removeUpdates(this);listener=null;position(location);}public void onProviderDisabled(String p){}public void onProviderEnabled(String p){}public void onStatusChanged(String p,int status,Bundle extras){}};
  boolean requested=false;for(String provider:new String[]{LocationManager.NETWORK_PROVIDER,LocationManager.GPS_PROVIDER})if(locations.isProviderEnabled(provider)){locations.requestLocationUpdates(provider,1000,0,listener);requested=true;}if(!requested){summary.setText("请开启系统定位，或手动填写城市。");return;}handler.postDelayed(()->{if(listener!=null){locations.removeUpdates(listener);listener=null;summary.setText("定位超时，请重试或手动填写城市。");}},15000);
 }catch(SecurityException e){error("请允许应用使用位置，或手动填写城市。");}}
 private void position(Location location){double[] gcj=Coordinates.gcj(location.getLatitude(),location.getLongitude());lat=gcj[0];lng=gcj[1];mapPanel.center(lat,lng);summary.setText("已定位，正在获取所在城市…");busy=true;worker.execute(()->{try{JSONObject data=api.json("/api/map-service",ApiClient.object("action","reverse","lat",lat,"lng",lng));handler.post(()->{if(isDestroyed())return;busy=false;String name=data.optString("city");if(!name.isEmpty()){locationCity=name;city.setText(name);}summary.setText("已获取当前位置；填写餐厅名称后搜索。");});}catch(Exception e){handler.post(()->{if(isDestroyed())return;busy=false;summary.setText("已定位，请手动填写城市后搜索。");});}});}
 private void selectPlace(JSONObject p){mapPanel.center(p.optDouble("lat"),p.optDouble("lng"));new AlertDialog.Builder(this).setTitle(p.optString("name","地图选点")).setMessage(p.optString("address")+"\n使用这个地点作为餐厅位置？").setPositiveButton("选择此地点",(d,w)->{Intent result=new Intent();result.putExtra("place",p.toString());setResult(RESULT_OK,result);finish();}).setNegativeButton("继续查看地图",null).show();}
 private void pickPoint(double lat,double lng){if(busy)return;busy=true;summary.setText("正在读取地图位置…");worker.execute(()->{try{JSONObject r=api.json("/api/map-service",ApiClient.object("action","reverse","lat",lat,"lng",lng));JSONArray list=r.optJSONArray("places");JSONObject p=list!=null&&list.length()>0?list.optJSONObject(0):ApiClient.object("name","地图选点","address",r.optString("address"),"lat",lat,"lng",lng,"system","gcj02");handler.post(()->{if(isDestroyed())return;busy=false;summary.setText("已读取地图位置");selectPlace(p);});}catch(Exception e){handler.post(()->{busy=false;if(!isDestroyed())error("无法读取位置，请重新点选或搜索餐厅。");});}});}
 private void pickDetails(JSONObject p){if(busy)return;busy=true;worker.execute(()->{try{JSONObject r=api.json("/api/map-service",ApiClient.object("action","details","id",p.optString("id")));JSONArray list=r.optJSONArray("places");JSONObject full=list!=null&&list.length()>0?list.optJSONObject(0):p;handler.post(()->{if(isDestroyed())return;busy=false;selectPlace(full);});}catch(Exception e){handler.post(()->{if(isDestroyed())return;busy=false;pickPoint(p.optDouble("lat"),p.optDouble("lng"));});}});}
 @Override protected void onResume(){super.onResume();if(mapPanel!=null)mapPanel.resume();}
 @Override protected void onPause(){if(mapPanel!=null)mapPanel.pause();super.onPause();}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==100){if(checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED)locate();else summary.setText("定位未授权，请手动填写城市。");}}
 @Override protected void onSaveInstanceState(Bundle state){if(mapPanel!=null)mapPanel.save(state);state.putString("locationCity",locationCity);state.putString("city",city.getText().toString());state.putString("keyword",keyword.getText().toString());state.putDouble("lat",lat);state.putDouble("lng",lng);super.onSaveInstanceState(state);}
 @Override protected void onDestroy(){if(mapPanel!=null)mapPanel.destroy();handler.removeCallbacksAndMessages(null);if(locations!=null&&listener!=null)locations.removeUpdates(listener);worker.shutdownNow();super.onDestroy();}
}
